import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Languages, Globe } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

function LanguageToggle() {
  const { language, toggleLanguage, translate } = useLanguage();

  return (
    <Button
      variant="outline"
      size="sm"
      onClick={toggleLanguage}
      className="flex items-center gap-2 border-2 transition-all duration-300 hover:scale-105"
      style={{
        borderColor: 'var(--brand-gray)',
        backgroundColor: 'var(--brand-gray-light)'
      }}
    >
      <Globe className="h-4 w-4" />
      <Badge 
        variant="secondary" 
        className="text-xs font-medium"
        style={{
          backgroundColor: language === 'ar' ? 'var(--brand-orange)' : 'var(--brand-gray)',
          color: 'white'
        }}
      >
        {language === 'ar' ? 'العربية' : 'English'}
      </Badge>
      <span className="text-xs">
        {language === 'ar' ? 'EN' : 'عربي'}
      </span>
    </Button>
  );
}

export default LanguageToggle;
